fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We maintain a half-open interval [low, high) in which we know
    // the target k must lie. Since k is guaranteed to be in v,
    // at the end low == high and v[low] == k.
    let mut low = 0;
    let mut high = v.len();

    while low < high {
        // Avoid overflow; this always produces a mid in [low, high)
        let mid = low + (high - low) / 2;
        if v[mid] < k {
            // If v[mid] is still less than k, the target must be to the right
            low = mid + 1;
        } else {
            // Otherwise, the target is at mid or to the left
            high = mid;
        }
    }

    // At this point low == high, and because k is guaranteed to be in v,
    // v[low] == k and low is a valid index.
    low
}

